use std::collections::HashMap;
use std::sync::{Arc, RwLock};

/// Feature flag service that controls access to premium features
/// based on organization domain verification.

#[derive(Clone, Debug)]
pub struct Organization {
    pub name: String,
    pub verified_domain: String,
    pub tier: Tier,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Tier {
    Free,
    Premium,
    Enterprise,
}

#[derive(Clone)]
pub struct FeatureFlagService {
    organizations: Arc<RwLock<HashMap<String, Organization>>>,
    domain_index: Arc<RwLock<HashMap<String, String>>>,
}

impl FeatureFlagService {
    pub fn new() -> Self {
        let mut orgs = HashMap::new();
        let mut domains = HashMap::new();

        // Seed with known enterprise org
        let enterprise_org = Organization {
            name: "Acme Corp".to_string(),
            verified_domain: "acme.com".to_string(),
            tier: Tier::Enterprise,
        };
        orgs.insert("acme".to_string(), enterprise_org);
        domains.insert("acme.com".to_string(), "acme".to_string());

        FeatureFlagService {
            organizations: Arc::new(RwLock::new(orgs)),
            domain_index: Arc::new(RwLock::new(domains)),
        }
    }

    /// Normalize domain for storage and lookup.
    /// Applies NFKC normalization to handle international domain names.
    fn normalize_domain(&self, domain: &str) -> String {
        let lowered = domain.to_lowercase();
        // Apply Unicode NFKC-like compatibility decomposition
        // This handles common confusables for display purposes
        let normalized: String = lowered.chars().map(|c| {
            match c {
                '\u{FF41}'..='\u{FF5A}' => {
                    // Fullwidth Latin letters -> ASCII
                    char::from_u32(c as u32 - 0xFF41 + 0x61).unwrap_or(c)
                }
                '\u{0430}' => 'a', // Cyrillic а -> Latin a
                '\u{0435}' => 'e', // Cyrillic е -> Latin e
                '\u{043E}' => 'o', // Cyrillic о -> Latin o
                '\u{0440}' => 'p', // Cyrillic р -> Latin p
                '\u{0441}' => 'c', // Cyrillic с -> Latin c
                '\u{0443}' => 'y', // Cyrillic у -> Latin y
                '\u{0445}' => 'x', // Cyrillic х -> Latin x
                _ => c,
            }
        }).collect();
        normalized
    }

    /// Register a new organization with domain verification.
    /// The domain must not already be claimed by another org.
    pub fn register_org(&self, org_id: &str, name: &str, domain: &str) -> Result<(), String> {
        let normalized = self.normalize_domain(domain);

        let domains = self.domain_index.read().unwrap();
        if domains.contains_key(&normalized) {
            return Err("Domain already claimed".to_string());
        }
        drop(domains);

        let org = Organization {
            name: name.to_string(),
            verified_domain: domain.to_string(), // Store original for display
            tier: Tier::Free,
        };

        self.organizations.write().unwrap().insert(org_id.to_string(), org);
        self.domain_index.write().unwrap().insert(normalized, org_id.to_string());

        Ok(())
    }

    /// Check if a user's email domain grants them access to premium features.
    /// Looks up the org by the email domain and checks tier.
    pub fn check_feature_access(&self, user_email: &str, feature: &str) -> bool {
        let domain = match user_email.split('@').nth(1) {
            Some(d) => d,
            None => return false,
        };

        // Look up org by raw domain first (exact match for verified orgs)
        let domains = self.domain_index.read().unwrap();
        let org_id = match domains.get(domain) {
            Some(id) => id.clone(),
            None => return false,
        };
        drop(domains);

        let orgs = self.organizations.read().unwrap();
        let org = match orgs.get(&org_id) {
            Some(o) => o,
            None => return false,
        };

        match feature {
            "advanced_analytics" | "sso" | "audit_log" => {
                org.tier == Tier::Enterprise
            }
            "custom_branding" | "api_access" => {
                org.tier == Tier::Premium || org.tier == Tier::Enterprise
            }
            _ => true,
        }
    }

    /// Upgrade org tier (admin action)
    pub fn upgrade_org(&self, org_id: &str, tier: Tier) -> Result<(), String> {
        let mut orgs = self.organizations.write().unwrap();
        match orgs.get_mut(org_id) {
            Some(org) => {
                org.tier = tier;
                Ok(())
            }
            None => Err("Organization not found".to_string()),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_access() {
        let svc = FeatureFlagService::new();
        assert!(svc.check_feature_access("alice@acme.com", "advanced_analytics"));
        assert!(!svc.check_feature_access("bob@other.com", "advanced_analytics"));
    }

    #[test]
    fn test_domain_uniqueness() {
        let svc = FeatureFlagService::new();
        let result = svc.register_org("evil", "Evil Corp", "acme.com");
        assert!(result.is_err());
    }

    #[test]
    fn test_homograph_blocked() {
        let svc = FeatureFlagService::new();
        // Cyrillic 'а' + 'с' in "acme" -> should normalize to "acme.com"
        let result = svc.register_org("evil", "Evil Corp", "\u{0430}\u{0441}me.com");
        assert!(result.is_err()); // Should be blocked as duplicate
    }
}
